#include <bits/stdc++.h>
using namespace std;const int N=524288,P=998244353,G=3,M=100005,S=2100000;static int a[N],b[N],c[N],d[N],r[N],j[N],v[N],t[S],y[S],u[4*M],z[4*M],x[M],h[M],o[M];static int n,e,k;
int pw(int a,int b=P-2){int s=1;for(;b;b>>=1,a=1LL*a*a%P)if(b&1)s=1LL*s*a%P;return s;}void f(int*a,int n,int q){for(int i=0;i<n;i++)if(i<r[i])swap(a[i],a[r[i]]);for(int l=2;l<=n;l<<=1){int w=pw(G,(P-1)/l);if(q<0)w=pw(w);for(int i=0;i<n;i+=l)for(int j=0,s=1;j<l/2;j++,s=1LL*s*w%P){int x=a[i+j],y=1LL*s*a[i+j+l/2]%P;a[i+j]=(x+y)%P;a[i+j+l/2]=(x-y+P)%P;}}if(q<0){int w=pw(n);for(int i=0;i<n;i++)a[i]=1LL*a[i]*w%P;}}void ml(const int*x,int n,const int*y,int m,int*o){int l=n+m-1;if(1LL*n*m<=256){memset(o,0,l*sizeof(int));for(int i=0;i<n;i++)for(int j=0;j<m;j++)o[i+j]=(o[i+j]+1LL*x[i]*y[j])%P;return;}int q=1,s=0;while(q<l)q<<=1,s++;memset(a,0,q*sizeof(int));memset(b,0,q*sizeof(int));memcpy(a,x,n*sizeof(int));memcpy(b,y,m*sizeof(int));r[0]=0;for(int i=1;i<q;i++)r[i]=(r[i>>1]>>1)|((i&1)<<(s-1));f(a,q,1);f(b,q,1);for(int i=0;i<q;i++)a[i]=1LL*a[i]*b[i]%P;f(a,q,-1);memcpy(o,a,l*sizeof(int));}void iv(const int*x,int n,int*y){memset(y,0,n*sizeof(int));y[0]=pw(x[0]);for(int k=1;k<n;k<<=1){int l=min(k<<1,n),q=1,s=0;while(q<l*2)q<<=1,s++;memset(a,0,q*sizeof(int));memset(b,0,q*sizeof(int));memcpy(a,x,l*sizeof(int));memcpy(b,y,k*sizeof(int));r[0]=0;for(int i=1;i<q;i++)r[i]=(r[i>>1]>>1)|((i&1)<<(s-1));f(a,q,1);f(b,q,1);for(int i=0;i<q;i++)b[i]=1LL*b[i]*(2-1LL*a[i]*b[i]%P+P)%P;f(b,q,-1);memcpy(y+k,b+k,(l-k)*sizeof(int));}}void md(const int*x,int n,const int*g,int m,int*o){if(n<m){memcpy(o,x,n*sizeof(int));memset(o+n,0,(m-1-n)*sizeof(int));return;}if(m<=32){memcpy(c,x,n*sizeof(int));int w=pw(g[m-1]);for(int i=n-1;i>=m-1;i--){int s=1LL*c[i]*w%P;for(int j=0;j<m;j++)c[i-m+1+j]=(c[i-m+1+j]-1LL*s*g[j]%P+P)%P;}memcpy(o,c,(m-1)*sizeof(int));return;}int q=n-m+1;memset(c,0,q*sizeof(int));for(int i=0;i<m&&i<q;i++)c[i]=g[m-1-i];iv(c,q,d);for(int i=0;i<q;i++)j[i]=x[n-1-i];ml(j,q,d,q,c);for(int i=0;i<q;i++)j[i]=c[q-1-i];ml(g,m,j,q,c);for(int i=0;i<m-1;i++)o[i]=(x[i]-c[i]+P)%P;}
void bd(int q,int l,int h0){if(l==h0){u[q]=e;z[q]=2;t[e++]=(P-x[l])%P;t[e++]=1;return;}int m=(l+h0)>>1;bd(q<<1,l,m);bd(q<<1|1,m+1,h0);u[q]=e;z[q]=z[q<<1]+z[q<<1|1]-1;ml(t+u[q<<1],z[q<<1],t+u[q<<1|1],z[q<<1|1],t+e);e+=z[q];}void ev(int q,int l,int h0,const int*p,int n){if(l==h0){h[l]=p[0];return;}int m=(l+h0)>>1,L=z[q<<1]-1,R=z[q<<1|1]-1,s=k;k+=L;md(p,n,t+u[q<<1],z[q<<1],y+s);int j=k;k+=R;md(p,n,t+u[q<<1|1],z[q<<1|1],y+j);ev(q<<1,l,m,y+s,L);ev(q<<1|1,m+1,h0,y+j,R);}int ip(int q,int l,int h0){if(l==h0){int s=e++;y[s]=1LL*o[l]*pw(h[l])%P;return s;}int m=(l+h0)>>1,L=ip(q<<1,l,m),R=ip(q<<1|1,m+1,h0),p=e;e+=h0-l+1;ml(y+L,m-l+1,t+u[q<<1|1],z[q<<1|1],c);memcpy(y+p,c,(h0-l+1)*sizeof(int));ml(y+R,h0-m,t+u[q<<1],z[q<<1],c);for(int i=0;i<=h0-l;i++)y[p+i]=(y[p+i]+c[i])%P;return p;}int main(){ios::sync_with_stdio(0);cin.tie(0);cin>>n;for(int i=0;i<n;i++)cin>>x[i]>>o[i];bd(1,0,n-1);for(int i=1;i<=n;i++)v[i-1]=1LL*i*t[u[1]+i]%P;k=0;ev(1,0,n-1,v,n);e=0;int s=ip(1,0,n-1);for(int i=0;i<n;i++)cout<<y[s+i]<<' ';cout<<'\n';}
